<script setup lang="ts">
import {ref,watch} from 'vue'
import {request,navigate,token,type Row} from '../../api/platform'
const props=defineProps<{activityId:string,activity:Row}>(),emit=defineEmits<{(e:'changed'):void}>()
const fields=ref<Row[]>([]),answers=ref<Row>({}),registration=ref<Row|null>(null),error=ref(''),busy=ref(false)
async function load(){if(!props.activity.form?.schemaJson)return;fields.value=JSON.parse(props.activity.form.schemaJson).fields;if(token()){const regs=await request<Row[]>('GET','/api/v1/me/registrations');registration.value=regs.find(r=>r.activityId===props.activityId)||null}}
async function submit(){if(!token()){navigate('login');return}busy.value=true;error.value='';try{registration.value=await request('POST','/api/v1/me/activities/'+props.activityId+'/registration',{formVersionId:props.activity.form.id,answers:answers.value});emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function cancel(){busy.value=true;try{await request('DELETE','/api/v1/me/activities/'+props.activityId+'/registration');emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(()=>props.activity,()=>{error.value='';load().catch(e=>error.value=(e as Error).message)},{immediate:true})
</script>
<template><text role="alert" class="error">{{ error }}</text><view v-if="registration&&registration.status!=='CANCELLED'" class="card"><text class="card-title">{{ registration.status==='CONFIRMED'?'报名已确认':'候补中' }}</text><text class="muted">{{ registration.status==='WAITLISTED'?'有人取消后会按报名顺序推进候补。':'请按活动安排参加。' }}</text><button role="button" class="danger" style="margin-top:18px" :disabled="busy" @click="cancel">取消报名</button></view><view v-else-if="fields.length>0" class="card"><text class="card-title">填写报名信息</text><view v-for="field in fields" :key="field.key" class="field"><text class="field-label">{{ field.label }} {{ field.required?'*':'' }}</text><picker v-if="field.type==='CHOICE'" :range="field.choices" @change="answers[field.key]=field.choices[Number($event.detail.value)]"><view class="picker">{{ answers[field.key]||'请选择' }}</view></picker><input v-else v-model="answers[field.key]" :type="field.type==='NUMBER'?'digit':'text'" :maxlength="field.maxLength" /></view><button role="button" :disabled="busy" @click="submit">{{ activity.remaining>0?'提交报名':activity.waitlistEnabled?'加入候补':'名额已满' }}</button></view></template>
